                            vt_letter(strs,out,"O");out.push_str(&format!("    jmp .Lvtobjend{k}\n.Lvtobjnil{k}:\n"));vt_letter(strs,out,"U");out.push_str(&format!(".Lvtobjend{k}:\n"));
