                            out.push_str(&format!("    mov -{}(%rbp), %r11\n", var.off));
                            out.push_str("    dec %rax\n    shl $4, %rax\n    add %r11, %rax\n    mov 8(%rax), %rcx\n    mov (%rax), %rax\n    jmp 94f\n93:\n    call hbc_bound_error\n94:\n");
