                                // an owned tag-4 casilla at the boundary.
                                out.push_str("    mov %rax, %rdi\n    mov %rdx, %rsi\n    call hbc_strcpy\n");
                                out.push_str("    mov %rax, %rdx\n    mov $4, %eax\n");
